import React, { useState, useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { MessageSquare, X, Send, Sparkles, GraduationCap, Briefcase, Phone, BookOpen, User, HelpCircle, Loader2 } from 'lucide-react';
import { client } from '../../lib/sanity';

const Chatbot = () => {
    const [isOpen, setIsOpen] = useState(false);
    const [messages, setMessages] = useState([
        { 
            sender: 'bot', 
            text: 'Hello! I am the CEC Virtual Assistant. How can I help you today?',
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        }
    ]);
    const [input, setInput] = useState('');
    const [loading, setLoading] = useState(false);
    const [siteData, setSiteData] = useState(null);
    const [initialized, setInitialized] = useState(false);
    const chatEndRef = useRef(null);

    // Initial Suggestions
    const suggestions = [
        { label: 'Admissions 2026', icon: <GraduationCap size={14} />, text: 'Tell me about Admissions 2026' },
        { label: 'Placements Rate', icon: <Briefcase size={14} />, text: 'What is the placement record?' },
        { label: 'Who is the Principal?', icon: <User size={14} />, text: 'Who is the Principal of CEC?' },
        { label: 'Contact Details', icon: <Phone size={14} />, text: 'What are the contact details?' }
    ];

    // Scroll to bottom on new message
    useEffect(() => {
        chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [messages, loading]);

    // Fetch site data on open
    useEffect(() => {
        if (isOpen && !initialized) {
            setLoading(true);
            const query = `{
                "departments": *[_type == "department"] { name, slug, overview, vision, mission, labsExtended, programmes },
                "placements": *[_type == "placement"] | order(year asc) { year, totalOffers, highestPackage },
                "principal": *[_type == "principal"][0] { name, message },
                "teachers": *[_type == "teacher"] { name, designation, department, email, phone },
                "organizations": *[_type == "organization"] { name, slug, fullName, description, majorActivities },
                "pages": *[_type == "pageContent"] { title, slug, content },
                "downloads": *[_type == "downloadCategory"] { title, files[] { title, "url": file.asset->url } },
                "announcements": *[_type == "announcement"] | order(date desc) [0..2] { title, content, date },
                "events": *[_type == "eventNews"] | order(date desc) [0..2] { title, content, date }
            }`;

            client.fetch(query)
                .then(data => {
                    setSiteData(data);
                    setInitialized(true);
                    setLoading(false);
                })
                .catch(err => {
                    console.error("Chatbot failed to load knowledge base:", err);
                    setLoading(false);
                });
        }
    }, [isOpen, initialized]);

    // Simple rich link generator parser
    const renderMessageText = (text) => {
        // Matches markdown [Text](Link) and turns it into React Router Link or normal Anchor
        const regex = /\[([^\]]+)\]\(([^)]+)\)/g;
        let lastIndex = 0;
        const result = [];
        let match;

        while ((match = regex.exec(text)) !== null) {
            // Push text before link
            if (match.index > lastIndex) {
                result.push(text.substring(lastIndex, match.index));
            }
            
            const linkText = match[1];
            const linkUrl = match[2];

            if (linkUrl.startsWith('/')) {
                result.push(
                    <Link key={match.index} to={linkUrl} className="text-accent underline font-bold hover:text-secondary transition" onClick={() => setIsOpen(false)}>
                        {linkText}
                    </Link>
                );
            } else {
                result.push(
                    <a key={match.index} href={linkUrl} target="_blank" rel="noopener noreferrer" className="text-accent underline font-bold hover:text-secondary transition">
                        {linkText}
                    </a>
                );
            }
            lastIndex = regex.lastIndex;
        }

        if (lastIndex < text.length) {
            result.push(text.substring(lastIndex));
        }

        return result.length > 0 ? result : text;
    };

    // Query processing engine
    const processQuery = (rawQuery) => {
        const q = rawQuery.toLowerCase().trim();
        const data = siteData;

        if (!data) {
            return "I am still initializing my knowledge base. Please try asking in a moment!";
        }

        // 1. Greetings
        if (['hello', 'hi', 'hey', 'hola', 'greetings', 'morning', 'afternoon'].some(w => q === w || q.startsWith(w + ' '))) {
            return "Hello! I am the CEC Assistant, loaded with information directly from the college database. How can I help you today?";
        }

        // 2. Principal
        if (q.includes('principal') || q.includes('head of college') || q.includes('who is leading') || q.includes('who runs')) {
            const name = data.principal?.name || "Dr. Jyothijohn";
            const msg = data.principal?.message ? `"${data.principal.message.substring(0, 120)}..."` : "committed to academic leadership and development.";
            return `The Principal of College of Engineering Chengannur is **${name}**. Here is a snippet of the Principal's address: ${msg} You can read the full message on our [Principal's Page](/page/principal).`;
        }

        // 3. Admissions / Courses
        if (q.includes('admission') || q.includes('join') || q.includes('apply') || q.includes('eligibility') || q.includes('seat')) {
            return "College of Engineering Chengannur offers B.Tech (Undergraduate) and MCA (Postgraduate) courses. Admissions are managed under IHRD guidelines and APJ Abdul Kalam Technological University. You can view the application process, fee structures, and seat allocations on our [Admissions Page](/page/admission-2026).";
        }

        // 4. Placements
        if (q.includes('placement') || q.includes('job') || q.includes('package') || q.includes('recruit') || q.includes('career') || q.includes('salary')) {
            if (data.placements && data.placements.length > 0) {
                const latest = data.placements[data.placements.length - 1];
                return `We have an outstanding placement cell at CEC! For the year ${latest.year}, we secured **${latest.totalOffers} total offers** with a highest package of **${latest.highestPackage}**. Top global companies like TCS, Infosys, Wipro, and key startups regularly recruit from our campus. Check full stats on the [Placement Page](/page/placement).`;
            }
            return "College of Engineering Chengannur features a highly active Training and Placement Cell securing placements with top-tier companies. Explore placement history on our [Placement Page](/page/placement).";
        }

        // 5. Contacts / Location / Address
        if (q.includes('contact') || q.includes('phone') || q.includes('email') || q.includes('address') || q.includes('location') || q.includes('map') || q.includes('where is')) {
            return "College of Engineering Chengannur is located at: \n**Chengannur, Alappuzha District, Kerala, India - 689121**.\n\n* **Phone:** +91-479-2454125\n* **Email:** principal@ceconline.edu\n\nFind our dynamic location map and contact lists on our [Contact Page](/page/contact).";
        }

        // 6. Specific Department Match
        if (q.includes('computer') || q.includes('cs') || q.includes('it')) {
            const cs = data.departments?.find(d => d.slug?.current?.includes('computer'));
            if (cs) {
                return `**${cs.name}** Department at CEC: ${cs.overview ? cs.overview.substring(0, 220) + '...' : ''} We run premium labs and comprehensive B.Tech/M.Tech/Ph.D courses. Read full details on the [Computer Engineering Page](/page/${cs.slug.current}).`;
            }
        }
        if (q.includes('electronics') || q.includes('ec')) {
            const ec = data.departments?.find(d => d.slug?.current?.includes('electronics'));
            if (ec) {
                return `**${ec.name}** Department at CEC: ${ec.overview ? ec.overview.substring(0, 220) + '...' : ''} Focuses heavily on embedded systems, IoT, and communication networks. Explore on the [Electronics Engineering Page](/page/${ec.slug.current}).`;
            }
        }
        if (q.includes('electrical') || q.includes('eee') || q.includes('electricity')) {
            const eee = data.departments?.find(d => d.slug?.current?.includes('electrical'));
            if (eee) {
                return `**${eee.name}** Department: ${eee.overview ? eee.overview.substring(0, 220) + '...' : ''} Focuses on power engineering, automation systems, and renewable energy. Read more on the [Electrical Engineering Page](/page/${eee.slug.current}).`;
            }
        }
        if (q.includes('general engineering') || q.includes('general') || q.includes('chemistry') || q.includes('math') || q.includes('physics')) {
            const ge = data.departments?.find(d => d.slug?.current?.includes('general'));
            if (ge) {
                return `**${ge.name}** handles foundational engineering subjects, physics, mathematics, and chemistry for first-year courses. View more details on the [General Engineering Page](/page/${ge.slug.current}).`;
            }
        }

        // 7. General Departments
        if (q.includes('department') || q.includes('course') || q.includes('programme') || q.includes('syllabus')) {
            const deptsList = data.departments?.map(d => `* [${d.name}](/page/${d.slug?.current})`).join('\n') || '';
            return `CEC offers specialized engineering departments including:\n${deptsList}\n\nYou can learn more by clicking on any department above!`;
        }

        // 8. Clubs & Organizations (PRODDEC, NSS, NCC, IEEE, etc.)
        if (q.includes('proddec')) {
            const proddec = data.organizations?.find(o => o.slug?.current?.includes('proddec'));
            if (proddec) {
                return `**PRODDEC** (Product Design & Development Centre): ${proddec.description || 'A highly proactive student forum focused on modern design, innovation, and coding products.'} Visit the [PRODDEC Details Page](/organization/proddec).`;
            }
        }
        if (q.includes('nss')) {
            const nss = data.organizations?.find(o => o.slug?.current?.includes('nss'));
            if (nss) {
                return `**NSS** (National Service Scheme) at CEC: Dedicated to community service, social drives, and student character-building. Details on [NSS Page](/organization/nss).`;
            }
        }
        if (q.includes('ncc')) {
            const ncc = data.organizations?.find(o => o.slug?.current?.includes('ncc'));
            if (ncc) {
                return `**NCC** (National Cadet Corps) at CEC: Imparts disciplined training, unity, and patriotic values to engineering students. Details on [NCC Page](/organization/ncc).`;
            }
        }
        if (q.includes('club') || q.includes('organization') || q.includes('society') || q.includes('nss') || q.includes('ncc') || q.includes('ieee') || q.includes('iedc') || q.includes('cell')) {
            const orgsList = data.organizations?.map(o => `* [${o.fullName || o.name}](/organization/${o.slug?.current})`).join('\n') || '';
            return `CEC has a highly vibrant student community. Active technical cells and organizations include:\n${orgsList}`;
        }

        // 9. Downloads & Files
        if (q.includes('download') || q.includes('pdf') || q.includes('form') || q.includes('circular') || q.includes('document')) {
            return "You can download university circulars, exam syllabus sheets, academic calendars, and administrative application forms directly from the college [Downloads & Forms Page](/page/downloads).";
        }

        // 10. Campus Life / Hostels / Library
        if (q.includes('campus') || q.includes('life') || q.includes('hostel') || q.includes('library') || q.includes('canteen') || q.includes('facility') || q.includes('sport')) {
            return "Our college provides modern libraries, well-equipped labs, student hostels, sports grounds, and active campus hubs. Read all details on the [Campus Life Page](/page/campus-life).";
        }

        // 11. Specific Teacher / Faculty Search
        if (q.includes('teacher') || q.includes('faculty') || q.includes('professor') || q.includes('staff')) {
            // Check if user is searching for a name
            const matchingTeachers = data.teachers?.filter(t => q.includes(t.name.toLowerCase()));
            if (matchingTeachers && matchingTeachers.length > 0) {
                const list = matchingTeachers.map(t => `* **${t.name}**: ${t.designation} (${t.department || 'CEC Staff'})`).join('\n');
                return `I found the following faculty members matching your search:\n${list}\n\nFor the complete directory, visit the [Faculty Directory](/page/teachers).`;
            }
            return "You can browse our full directory of professors, teachers, and support coordinators on the [Faculty Directory](/page/teachers). Details on administrative and library staff are available on the [Administrative Staff](/page/administrative-staff) and [Library Staff](/page/library-staff) pages.";
        }

        // 12. Latest Updates / News / Announcements
        if (q.includes('news') || q.includes('announcement') || q.includes('latest') || q.includes('update') || q.includes('event')) {
            const items = [];
            if (data.announcements && data.announcements.length > 0) {
                items.push(`**Latest Announcement:** "${data.announcements[0].title}" (${data.announcements[0].date})`);
            }
            if (data.events && data.events.length > 0) {
                items.push(`**Featured Event:** "${data.events[0].title}" (${data.events[0].date})`);
            }
            if (items.length > 0) {
                return `Here are the latest happenings on campus:\n\n${items.join('\n\n')}\n\nYou can keep check of details on the homepage updates panel!`;
            }
            return "Check our latest newsletters, academic updates, and events directly on the main website homepage updates dashboard.";
        }

        // 13. Deep content search fallback (Paragraph match)
        let bestMatch = null;
        let highestScore = 0;

        // Helper to score text matches
        const getScore = (text, queryWords) => {
            if (!text) return 0;
            const textLower = text.toLowerCase();
            return queryWords.reduce((score, word) => {
                if (word.length > 2 && textLower.includes(word)) {
                    return score + 1;
                }
                return score;
            }, 0);
        };

        const words = q.split(/\s+/).filter(w => w.length > 2);
        if (words.length > 0) {
            // Search Page contents
            data.pages?.forEach(page => {
                if (page.content) {
                    // Split content by paragraphs or double newlines
                    const paragraphs = page.content.split(/\n\n+/);
                    paragraphs.forEach(p => {
                        const score = getScore(p, words);
                        if (score > highestScore) {
                            highestScore = score;
                            bestMatch = {
                                text: p,
                                source: page.title,
                                link: `/page/${page.slug?.current}`
                            };
                        }
                    });
                }
            });

            // Search Department overviews
            data.departments?.forEach(dept => {
                const score = getScore(dept.overview, words);
                if (score > highestScore) {
                    highestScore = score;
                    bestMatch = {
                        text: dept.overview,
                        source: dept.name,
                        link: `/page/${dept.slug?.current}`
                    };
                }
            });
        }

        if (highestScore > 1 && bestMatch) {
            const cleanText = bestMatch.text.length > 300 ? bestMatch.text.substring(0, 297) + '...' : bestMatch.text;
            return `${cleanText}\n\n*(Source: [${bestMatch.source}](${bestMatch.link}))*`;
        }

        // 14. Ultimate Fallback
        return "I'm sorry, I couldn't find a specific detail on that in our CMS. \n\nYou might find what you are looking for by exploring our main pages:\n* **[Admissions 2026](/page/admission-2026)**\n* **[Placement Stats](/page/placement)**\n* **[Contact Desk](/page/contact)**\n* **[Faculty & Staff](/page/teachers)**\n\nOr feel free to ask me something else!";
    };

    // Send Message Handler
    const handleSend = (textToSend = input) => {
        if (!textToSend.trim()) return;

        const userMsg = {
            sender: 'user',
            text: textToSend,
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        };

        setMessages(prev => [...prev, userMsg]);
        setInput('');
        setLoading(true);

        setTimeout(() => {
            const botAnswer = processQuery(textToSend);
            const botMsg = {
                sender: 'bot',
                text: botAnswer,
                time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
            };
            setMessages(prev => [...prev, botMsg]);
            setLoading(false);
        }, 600);
    };

    return (
        <>
            {/* Floating Chatbot Toggle Button */}
            <button
                onClick={() => setIsOpen(!isOpen)}
                className={`fixed bottom-28 right-6 lg:bottom-32 lg:right-10 w-16 h-16 rounded-full shadow-[0_15px_40px_rgba(12,43,78,0.2)] bg-primary hover:bg-accent text-white flex items-center justify-center transition-all duration-300 transform hover:scale-105 z-[100] border-2 border-white/20`}
            >
                {isOpen ? <X size={24} /> : <MessageSquare size={24} />}
            </button>

            {/* Chat Panel */}
            <AnimatePresence>
                {isOpen && (
                    <motion.div
                        initial={{ opacity: 0, y: 50, scale: 0.95 }}
                        animate={{ opacity: 1, y: 0, scale: 1 }}
                        exit={{ opacity: 0, y: 50, scale: 0.95 }}
                        transition={{ duration: 0.3 }}
                        className="fixed bottom-[188px] right-6 w-[350px] sm:w-[400px] h-[500px] rounded-3xl bg-white/90 backdrop-blur-md border border-slate-100 shadow-[0_25px_60px_rgba(0,0,0,0.15)] z-[100] flex flex-col overflow-hidden text-left"
                    >
                        {/* Chat Panel Header */}
                        <div className="bg-primary px-6 py-4 flex items-center justify-between text-white border-b border-white/10">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 rounded-full bg-accent flex items-center justify-center shadow-inner">
                                    <Sparkles size={18} className="text-white" />
                                </div>
                                <div>
                                    <h3 className="font-display font-bold text-sm tracking-wide">CEC AI Assistant</h3>
                                    <span className="text-[10px] text-white/60 font-semibold tracking-wider uppercase">Online Knowledge</span>
                                </div>
                            </div>
                            <button onClick={() => setIsOpen(false)} className="text-white/60 hover:text-white transition">
                                <X size={18} />
                            </button>
                        </div>

                        {/* Message Box */}
                        <div className="flex-1 overflow-y-auto p-6 space-y-6 scrollbar-thin">
                            {messages.map((msg, i) => (
                                <div key={i} className={`flex gap-3 ${msg.sender === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                                    {msg.sender === 'bot' ? (
                                        <div className="w-8 h-8 rounded-full bg-accent flex items-center justify-center shrink-0 text-white shadow-sm">
                                            <Sparkles size={12} />
                                        </div>
                                    ) : (
                                        <div className="w-8 h-8 rounded-full bg-slate-200 flex items-center justify-center shrink-0 text-slate-600 font-bold text-xs">
                                            U
                                        </div>
                                    )}
                                    <div className="flex flex-col max-w-[75%]">
                                        <div className={`p-4 rounded-2xl text-sm leading-relaxed whitespace-pre-line font-medium shadow-sm border ${
                                            msg.sender === 'user' 
                                            ? 'bg-primary text-white border-primary/20 rounded-tr-none' 
                                            : 'bg-slate-50 text-secondary border-slate-100 rounded-tl-none'
                                        }`}>
                                            {renderMessageText(msg.text)}
                                        </div>
                                        <span className={`text-[9px] text-slate-400 font-bold mt-1.5 ${msg.sender === 'user' ? 'self-end' : 'self-start'}`}>
                                            {msg.time}
                                        </span>
                                    </div>
                                </div>
                            ))}

                            {/* Typing loader */}
                            {loading && (
                                <div className="flex gap-3 flex-row">
                                    <div className="w-8 h-8 rounded-full bg-accent flex items-center justify-center shrink-0 text-white animate-spin">
                                        <Loader2 size={12} />
                                    </div>
                                    <div className="p-4 rounded-2xl bg-slate-50 border border-slate-100 text-slate-400 text-xs flex items-center gap-2 font-bold rounded-tl-none shadow-sm">
                                        <span>Analyzing site content...</span>
                                    </div>
                                </div>
                            )}
                            <div ref={chatEndRef} />
                        </div>

                        {/* Suggestions */}
                        {messages.length === 1 && !loading && (
                            <div className="px-6 py-2 flex flex-wrap gap-2 border-t border-slate-50 bg-slate-50/50">
                                {suggestions.map((s, idx) => (
                                    <button 
                                        key={idx}
                                        onClick={() => handleSend(s.text)}
                                        className="flex items-center gap-1.5 px-3 py-1.5 bg-white border border-slate-100 hover:border-accent hover:bg-accent/5 rounded-full text-xs font-bold text-slate-500 hover:text-accent transition duration-200 shadow-sm"
                                    >
                                        {s.icon}
                                        <span>{s.label}</span>
                                    </button>
                                ))}
                            </div>
                        )}

                        {/* Input Area */}
                        <div className="p-4 border-t border-slate-100 bg-white flex items-center gap-3">
                            <input
                                type="text"
                                value={input}
                                onChange={(e) => setInput(e.target.value)}
                                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                                placeholder="Ask about admissions, placements, clubs..."
                                className="flex-1 px-4 py-3 bg-slate-50 focus:bg-white rounded-xl text-sm border border-slate-100 focus:border-accent focus:ring-2 focus:ring-accent/15 outline-none transition font-medium text-secondary"
                            />
                            <button 
                                onClick={() => handleSend()}
                                className="p-3 bg-primary hover:bg-accent text-white rounded-xl transition duration-200 shadow-md shrink-0"
                            >
                                <Send size={16} />
                            </button>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </>
    );
};

export default Chatbot;
